def main():
    try:
        raw = sys.stdin.buffer.read(MAX_INPUT_BYTES + 1)
        if len(raw) > MAX_INPUT_BYTES:
            raise Invalid()
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            raise Invalid()
        del raw
        try:
            doc = json.loads(text, parse_int=int, parse_float=_reject_float,
                             parse_constant=_reject_constant,
                             object_pairs_hook=_reject_duplicate)
        except ValueError:
            raise Invalid()
        except RecursionError:
            raise Invalid()
        del text
        result = _solve(doc)
        payload = json.dumps(result, separators=(",", ":")).encode("utf-8")
    except Invalid:
        payload = ERROR_BYTES
    except Exception:
        traceback.print_exc()
        payload = ERROR_BYTES
    out = sys.stdout.buffer
    out.write(payload)
    out.flush()
    return 0


